// Copy onnxruntime-web's wasm asset into apps/web/public/ort/ so the B7 spike
// worker can load it same-origin (production CSP connect-src 'self', D23).
// The file is ~14 MB and gitignored — it is a build artifact of the pinned dep,
// regenerated by `pnpm --filter @airhythm/web prebuild` (and by the e2e server).
import { createRequire } from "node:module";
import { copyFileSync, mkdirSync, existsSync } from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

const require = createRequire(import.meta.url);
const here = path.dirname(fileURLToPath(import.meta.url));
const dest = path.resolve(here, "../public/ort");
mkdirSync(dest, { recursive: true });

// onnxruntime-web's `exports` map does not expose ./package.json, so resolve a
// known export and take its directory (…/onnxruntime-web/dist/ort.node.min.js).
const dist = path.dirname(require.resolve("onnxruntime-web"));
const files = ["ort-wasm-simd-threaded.mjs", "ort-wasm-simd-threaded.wasm"];
for (const f of files) {
  const src = path.join(dist, f);
  if (!existsSync(src)) throw new Error(`copy-ort-wasm: missing ${src} (is onnxruntime-web installed?)`);
  copyFileSync(src, path.join(dest, f));
}
console.log(`[copy-ort-wasm] copied ${files.length} files → apps/web/public/ort/`);
